f4","description":"Euclides","correct_answer":false},{"id":"01a218f9-3802-7042-8a18-94a6102cc4a9","description":"Ptolomeu","correct_answer":false},{"id":"01a218f9-3802-7d7d-a35c-93b194d0310b","description":"Hiparco","correct_answer":false}]},{"id":"01a218f9-3802-77dc-97bc-4a2e5b6ae926","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual f\u00edsico americano construiu o primeiro laser funcional em 1960, utilizando um cristal de rubi?","difficulty":3,"explanation":"O laser de rubi de Theodore Maiman utilizava uma l\u00e2mpada de flash para excitar o cristal, produzindo breves pulsos de luz vermelha.","alternatives":[{"id":"01a218f9-3802-74d1-a3a4-62c281eb9b23","description":"Theodore Maiman","correct_answer":true},{"id":"01a218f9-3802-7875-8d6d-c1e9e76a6864","description":"Charles Townes","correct_answer":false},{"id":"01a218f9-3802-7af5-b8fa-a797542bf638","description":"Gordon Gould","correct_answer":false},{"id":"01a218f9-3802-7c90-9845-ce035d1cfe6d","description":"Arthur Schawlow","correct_answer":false}]},{"id":"01a218f9-3802-74fb-94e6-44bc84e93ca6","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Onde podemos encontrar a membrana timp\u00e2nica?","difficulty":3,"explanation":"A membrana timp\u00e2nica vibra em resposta ao som e transmite essas vibra\u00e7\u00f5es aos tr\u00eas ossinhos do ouvido m\u00e9dio.","alternatives":[{"id":"01a218f9-3802-79ff-b793-39c9f282d924","description":"Ouvido","correct_answer":true},{"id":"01a218f9-3802-746f-96cc-9a4954f368d8","description":"Nariz","correct_answer":false},{"id":"01a218f9-3802-7e4b-b712-89adcb2837d2","description":"Boca","correct_answer":false},{"id":"01a218f9-3802-7d2b-96e4-f4d29aad7f68","description":"Olho","correct_answer":false}]},{"id":"01a218f9-3802-73f1-aedc-cfe2a1cee130","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual \u00e9 a palavra para designar um grupo de pardais?","difficulty":3,"explanation":"\u201cHost\u201d de pardais \u00e9 um substantivo coletivo tradicional; \u201chost\u201d tamb\u00e9m tem um sentido mais antigo de \u201cgrande multid\u00e3o\u201d.","alternatives":[{"id":"01a218f9-3802-73cb-94cb-e40c7e552b88","description":"Um bando","correct_answer":true},{"id":"01a218f9-3802-73a0-a2f3-67f20e747ae3","description":"Uma corrida","correct_answer":false},{"id":"01a218f9-3802-787d-b6b1-fde0c151438c","description":"Um campo","correct_answer":false},{"id":"01a218f9-3802-77ec-ac2b-1b5b14bfae60","description":"Um feiti\u00e7o","correct_answer":false}]},{"id":"01a218f9-3802-7470-9b74-c9f7438dc2bb","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"O que estuda a Kimatologia?","difficulty":3,"explanation":"O termo \u201cKimatologia\u201d deriva do grego \u201ckyma\u201d, que significa onda; essa \u00e1rea tamb\u00e9m se aplica aos movimentos do som e de outros sistemas f\u00edsicos.","alternatives":[{"id":"01a218f9-3802-721b-9e54-171a2bba9fcb","description":"ondas ou movimentos ondulat\u00f3rios","correct_answer":true},{"id":"01a218f9-3802-717b-80eb-1921dcfa58db","description":"clima","correct_answer":false},{"id":"01a218f9-3802-7cbe-b31a-394cc9f60801","description":"Tibete","correct_answer":false},{"id":"01a218f9-3802-771d-9e3a-734c68958ecf","description":"processos mentais em seres vivos","correct_answer":false}]},{"id":"01a218f9-3802-729d-ba0c-85b0dc643ddc","locale":"ptBR","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual \u00e9 o nome da camada externa r\u00edgida da Terra, composta pela crosta e pelo manto superior?","difficulty":3,"explanation":"A litosfera \u00e9 a camada externa r\u00edgida da Terra, com cerca de 100 km de espessura, dividida em placas tect\u00f4nicas.","alternatives":[{"id":"01a218f9-3802-77a9-a7aa-d32fbe677311","description":"Litosfera","correct_answer":true},{"id":"01a218f9-3802-767f-9ef1-eab661cfb5b9","description":"Atmosfera","correct_answer":false},{"id":"01a218f9-3802-7926-b957-7d05c810c6b9","descr